SELECT p.slug,p.display_name,count(DISTINCT r.id) FILTER (WHERE l.id IS NOT NULL)::bigint repositories,count(DISTINCT d.id) FILTER (WHERE dl.id IS NOT NULL)::bigint documents FROM projects p LEFT JOIN repositories r ON r.project_id=p.id LEFT JOIN repository_locations l ON l.repository_id=r.id AND EXISTS (SELECT 1 FROM unnest($1::text[]) AS allowed(root_path) WHERE l.root_path=allowed.root_path) LEFT JOIN source_documents d ON d.project_id=p.id LEFT JOIN repository_locations dl ON dl.id=d.repository_location_id AND EXISTS (SELECT 1 FROM unnest($1::text[]) AS allowed(root_path) WHERE dl.root_path=allowed.root_path) GROUP BY p.id HAVING count(DISTINCT l.id)>0 ORDER BY p.slug
